function run_test() {
  for (var index = 0; index < kValidScopes.length; ++index) {
    const scope = kValidScopes[index];
    const table = gValidityManager.getTable(scope);
    const attributes = table.getAvailableAttributes();
    let attribute;
    while ((attribute = attributes.pop()) && attribute) {
      const l10nID = gValidityManager.getAttributeL10nID(attribute);
      let valid = false;
      let localizedString;
      try {
        localizedString = l10n.formatValueSync(l10nID);
        valid = true;
      } catch (e) {
        dump("\n" + e);
      }
      valid = valid && localizedString && localizedString.length > 0;
      if (!valid) {
        dump(
          "\nNo valid string for scope = " +
            scope +
            " attribute = " +
            attribute +
            " L10n ID = " +
            l10nID
        );
      }
      Assert.ok(valid);
    }
  }
